<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { ArrowLeft, Connection, DocumentChecked } from '@element-plus/icons-vue'
import type { FormInstance, FormRules } from 'element-plus'
import { ApiError } from '../../../api/errors/ApiError'
import { useActorStore } from '../../../app/stores/actor'
import { useOverlayStore } from '../../../app/stores/overlays'
import type { SystemSummary } from '../../systems/api/systemsContracts'
import { integrationsApi } from '../api/integrationsApi'
import { integrationTypeLabels, integrationTypes, type IntegrationType, type IntegrationWriteResponse } from '../api/integrationContracts'
const props=defineProps<{systems:readonly SystemSummary[]}>();const emit=defineEmits<{created:[item:IntegrationWriteResponse]}>();const actors=useActorStore();const overlays=useOverlayStore();const formRef=ref<FormInstance>();const error=ref<string|null>(null);const submitting=ref(false)
const form=reactive({name:'',integrationType:'RabbitMq' as IntegrationType,sourceSystemId:null as number|null,sourcePartyName:'',targetSystemId:null as number|null,targetPartyName:'',flowDirection:'OneWay' as 'OneWay'|'Bidirectional',purpose:'',url:'',method:'GET',exchange:'',topic:'',queue:'',filePath:'',databaseSourceId:null as number|null,databaseObjectId:null as number|null})
const rules:FormRules<typeof form>={name:[{required:true,message:'请输入集成名称',trigger:'blur'}],sourcePartyName:[{required:true,message:'请输入来源方名称',trigger:'blur'}],targetPartyName:[{required:true,message:'请输入目标方名称',trigger:'blur'}]}
const endpointLabel=computed(()=>form.integrationType==='HttpApi'?'HTTP 地址':form.integrationType==='RabbitMq'?'Topic 或 Queue':form.integrationType==='FileExchange'?'文件路径':'数据库来源或对象')
function back(){overlays.openDialog({kind:'create-knowledge-object',id:null,mode:'create'})}
function endpoint():Record<string,string|null>{if(form.integrationType==='HttpApi')return{url:form.url.trim()||null,method:form.method.trim()||null};if(form.integrationType==='RabbitMq')return{exchange:form.exchange.trim()||null,topic:form.topic.trim()||null,queue:form.queue.trim()||null};if(form.integrationType==='FileExchange')return{filePath:form.filePath.trim()||null};return{}}
async function submit(){error.value=null;const valid=await formRef.value?.validate().catch(()=>false);if(!valid||submitting.value)return;if(form.sourceSystemId===null&&form.targetSystemId===null){error.value='来源方或目标方至少一端必须关联已登记系统。';return}submitting.value=true;try{emit('created',await integrationsApi.create({name:form.name.trim(),integrationType:form.integrationType,sourceParty:{systemId:form.sourceSystemId,displayName:form.sourcePartyName.trim()},targetParty:{systemId:form.targetSystemId,displayName:form.targetPartyName.trim()},flowDirection:form.flowDirection,purpose:form.purpose.trim()||null,endpoint:endpoint(),databaseSourceId:form.databaseSourceId,databaseObjectId:form.databaseObjectId,actor:actors.actor}))}catch(caught:unknown){error.value=caught instanceof ApiError?caught.message:caught instanceof Error?caught.message:'集成关系创建失败。'}finally{submitting.value=false}}
</script>
<template><section class="integration-create"><header class="authoring-header authoring-header--form"><div><button class="authoring-back" @click="back"><el-icon><ArrowLeft/></el-icon> 选择知识类型</button><h2>新增集成关系</h2><p>先记录参与方和技术端点；契约、关系和证据可以在创建后逐步补充。</p></div><button class="authoring-close" @click="overlays.closeDialog">×</button></header><div class="authoring-progression"><span class="authoring-progression__step authoring-progression__step--active"><b>1</b>基本信息（当前）</span><span class="authoring-progression__line"/><span class="authoring-progression__step"><b>2</b>关系（创建后）</span><span class="authoring-progression__line"/><span class="authoring-progression__step"><b>3</b>证据（创建后）</span></div><div class="integration-create__body"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-alert v-if="error" class="authoring-form-alert" type="error" :title="error" :closable="false" show-icon/><el-form-item label="集成名称" prop="name" required><el-input v-model="form.name" placeholder="例如 equipment.status.changed" class="technical-input"/></el-form-item><el-form-item label="集成类型" required><el-select v-model="form.integrationType"><el-option v-for="type in integrationTypes" :key="type" :value="type" :label="integrationTypeLabels[type]"/></el-select></el-form-item><div class="integration-create__two"><el-form-item label="来源方名称" prop="sourcePartyName" required><el-input v-model="form.sourcePartyName" placeholder="例如 MES"/></el-form-item><el-form-item label="来源方已登记系统（可选）"><el-select v-model="form.sourceSystemId" clearable filterable><el-option v-for="system in systems" :key="system.id" :value="system.id" :label="system.name"/></el-select></el-form-item><el-form-item label="目标方名称" prop="targetPartyName" required><el-input v-model="form.targetPartyName" placeholder="例如 Equipment Gateway"/></el-form-item><el-form-item label="目标方已登记系统（可选）"><el-select v-model="form.targetSystemId" clearable filterable><el-option v-for="system in systems" :key="system.id" :value="system.id" :label="system.name"/></el-select></el-form-item></div><el-form-item label="数据流向" required><el-radio-group v-model="form.flowDirection"><el-radio-button label="OneWay">单向</el-radio-button><el-radio-button label="Bidirectional">双向</el-radio-button></el-radio-group></el-form-item><el-form-item label="用途（可选）"><el-input v-model="form.purpose" type="textarea" :rows="2"/></el-form-item><el-divider content-position="left">{{ endpointLabel }}</el-divider><template v-if="form.integrationType==='HttpApi'"><el-form-item label="URL"><el-input v-model="form.url" class="technical-input" placeholder="https://gateway.example/api/status"/></el-form-item><el-form-item label="HTTP Method"><el-input v-model="form.method" class="technical-input"/></el-form-item></template><template v-else-if="form.integrationType==='RabbitMq'"><el-form-item label="Exchange（可选）"><el-input v-model="form.exchange" class="technical-input"/></el-form-item><el-form-item label="Topic"><el-input v-model="form.topic" class="technical-input" placeholder="equipment.status.changed"/></el-form-item><el-form-item label="Queue（可选）"><el-input v-model="form.queue" class="technical-input"/></el-form-item></template><template v-else-if="form.integrationType==='FileExchange'"><el-form-item label="文件路径"><el-input v-model="form.filePath" class="technical-input" placeholder="/drop/equipment-status.csv"/></el-form-item></template><template v-else><el-form-item label="数据库来源 ID"><el-input-number v-model="form.databaseSourceId" :min="1" controls-position="right"/></el-form-item><el-form-item label="数据库对象 ID（可选）"><el-input-number v-model="form.databaseObjectId" :min="1" controls-position="right"/></el-form-item></template></el-form><aside><h3>创建后的下一步</h3><div><el-icon><Connection/></el-icon><span><strong>添加关系</strong><small>连接业务功能、数据对象与参与系统</small></span></div><div><el-icon><DocumentChecked/></el-icon><span><strong>添加证据</strong><small>说明为什么相信该集成定义</small></span></div><section><span>知识状态</span><p>创建后保持“未知”，不会自动推进。</p><strong class="knowledge-status-badge knowledge-status-badge--unknown">未知</strong></section></aside></div><footer class="authoring-actions"><p>关系、证据和知识状态均需后续明确维护。</p><div><el-button @click="overlays.closeDialog">取消</el-button><el-button type="primary" :loading="submitting" @click="submit">创建集成关系</el-button></div></footer></section></template>
<style scoped>.integration-create__body{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:28px;padding:20px 28px}.integration-create__body aside{border-left:1px solid var(--el-border-color-lighter);padding-left:22px}.integration-create__body aside>div{display:flex;gap:10px;margin:13px 0}.integration-create__body aside small{display:block;color:var(--el-text-color-secondary);margin-top:3px}.integration-create__two{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}@media(max-width:720px){.integration-create__body,.integration-create__two{grid-template-columns:1fr}.integration-create__body aside{border-left:0;border-top:1px solid var(--el-border-color-lighter);padding:16px 0 0}}</style>
